113	test('npm-test-glob-coverage: fires on a test file no `test` pattern reaches', () => {
114	  const findings = npmTestGlobCoverage.run(
115	    globCtx(
116	      ['extension-test/host-policy.test.js', 'dev/security/csp.test.js'],
117	      SCRIPTS,
118	    ),
119	  );
120	  assert.equal(findings.length, 1);
121	  assert.equal(findings[0].file, 'dev/security/csp.test.js');
122	  assert.match(findings[0].what, /reached by no pattern/);
123	  assert.equal(findings[0].severity, 'blocking');
124	});
125	
126	test('npm-test-glob-coverage: quiet when every pattern shape reaches its files', () => {
127	  const findings = npmTestGlobCoverage.run(
128	    globCtx(
129	      [
130	        'extension-test/host-policy.test.js', // `**/` must match ZERO directories too
131	        'extension-test/events-popup/popup.test.js',
132	        'dev/build/test/load-order-generated.test.js',
133	        '.claudinite/local/packs/gcec/pack.test.mjs', // .mjs counts as a test file
134	        'dev/requirements/logic/product-requirements.test.js',
135	        'dev/requirements/requirements-coverage.test.js', // a literal path, not a glob
136	        'extension/host-policy.js', // not a test file at all
137	      ],
138	      SCRIPTS,
139	    ),
140	  );
141	  assert.deepEqual(findings, []);
142	});
143	
144	test('npm-test-glob-coverage: the heavy e2e suite is exempt via scripts["test:e2e"]', () => {
145	  const heavy = 'dev/requirements/heavy/extension-load.chrome.test.js';
146	  assert.deepEqual(npmTestGlobCoverage.run(globCtx([heavy], SCRIPTS)), []);
147	  // …and only because test:e2e declares it: drop that script and the carve-out goes.
148	  const findings = npmTestGlobCoverage.run(globCtx([heavy], { test: SCRIPTS.test }));
149	  assert.equal(findings.length, 1);
150	  assert.equal(findings[0].file, heavy);
151	});
152	
153	test('npm-test-glob-coverage: quiet when the test script is not a `node --test` runner', () => {
154	  const findings = npmTestGlobCoverage.run(
155	    globCtx(['dev/security/csp.test.js'], { test: 'jest' }),
156	  );
157	  assert.deepEqual(findings, []);
158	});
