160	// pipeline-site-agnostic reads the host list out of the repo, so every fixture
161	// tree carries a host-lists.json — the check follows that declaration, never a
162	// copy of it.
163	const HOSTS = JSON.stringify({
164	  supportedDomains: ['stubhub.com', 'tel-aviv.gov.il', 'visit.tel-aviv.gov.il', 'lu.ma'],
165	});
166	const pipelineCtx = (tree) => treeCtx({ 'extension/host-lists.json': HOSTS, ...tree });
167	
168	test('pipeline-site-agnostic: fires on a host in shipped pipeline code, in the generic extractor and in a helper', () => {
169	  const findings = pipelineSiteAgnostic.run(
170	    pipelineCtx({
171	      'extension/event-extractors/generic-extractor.js':
172	        'function read(doc) {\n  if (host.endsWith("stubhub.com")) return special(doc);\n  return generic(doc);\n}\n',
173	      'extension/event-extractors/helpers/derive-timezone.js':
174	        'const OVERRIDE = { "visit.tel-aviv.gov.il": "Asia/Jerusalem" };\n',
175	    }),
176	  );
177	  assert.equal(findings.length, 2);
178	  assert.equal(findings[0].file, 'extension/event-extractors/generic-extractor.js');
179	  assert.equal(findings[0].line, 2); // the blanked comments keep line numbers true
180	  assert.match(findings[0].what, /names the supported site stubhub\.com/);
181	  // the longest matching entry wins, not the one it contains
182	  assert.match(findings[1].what, /visit\.tel-aviv\.gov\.il/);
183	  assert.ok(findings.every((f) => f.severity === 'blocking'));
184	});
185	
186	test('pipeline-site-agnostic: fires on a host hidden in a URL string (the `//` must not read as a comment)', () => {
187	  const findings = pipelineSiteAgnostic.run(
188	    pipelineCtx({
189	      'extension/event-extractors/assemble-events.js':
190	        'const FEED = "https://lu.ma/api/events";\n',
191	    }),
192	  );
193	  assert.equal(findings.length, 1);
194	  assert.equal(findings[0].line, 1);
195	  assert.match(findings[0].what, /lu\.ma/);
196	});
197	
198	test('pipeline-site-agnostic: quiet when the sites are only cited in comments, or live in custom/', () => {
199	  const findings = pipelineSiteAgnostic.run(
200	    pipelineCtx({
201	      // citing where a generic pattern was observed is how this codebase records
202	      // evidence — both comment forms, and one on the same line as real code
203	      'extension/event-extractors/generic-extractor.js':
204	        '// or is merely the site\'s domain ("stubhub.com" is not a venue).\n' +
205	        '/* seen on visit.tel-aviv.gov.il\n   and lu.ma */\n' +
206	        'const venue = readVenue(doc); // not stubhub.com-specific\n',
207	      // per-site knowledge belongs here, and this check must never flag it
208	      'extension/event-extractors/custom/stubhub.js':
209	        'GCal.sources.push({ matches: (h) => /(^|\\.)stubhub\\.com$/.test(h) });\n',
210	      // a host-shaped substring is not the host
211	      'extension/event-extractors/helpers/text.js': 'const s = "notstubhub.combo";\n',
212	      // non-.js pipeline files are out of scope
213	      'extension/event-extractors/load-order.generated.json': '["stubhub.com"]',
214	    }),
215	  );
216	  assert.deepEqual(findings, []);
217	});
218	
219	test('pipeline-site-agnostic: quiet when the host list is missing or declares nothing', () => {
220	  const tree = {
221	    'extension/event-extractors/generic-extractor.js': 'if (h === "stubhub.com") {}\n',
222	  };
223	  assert.deepEqual(pipelineSiteAgnostic.run(treeCtx(tree)), []);
224	  assert.deepEqual(
225	    pipelineSiteAgnostic.run(treeCtx({ ...tree, 'extension/host-lists.json': '{"supportedDomains":[]}' })),
226	    [],
227	  );
228	});
