230	// regen-artifacts-merge-ours reads .gitattributes out of the fixture tree, so each
231	// tree pairs the artifacts with the driver list that is supposed to name them. The
232	// live repo's list, verbatim in shape, is the clean baseline every fixture varies.
233	const GITATTRIBUTES = [
234	  '# Generated/derived files — regenerated by `npm run regen`, never hand-merged.',
235	  '# extension/event-extractors/not-a-real-entry.json merge=ours   <- a comment, not an entry',
236	  'dev/requirements/extractor/data/**/*.html linguist-vendored',
237	  'extension/event-extractors/load-order.generated.json                merge=ours',
238	  'dev/requirements/extractor/generic-coverage/generic-coverage.baseline.GENERATED.json   merge=ours',
239	  'dev/requirements/popup/cases/*.png                                              merge=ours',
240	  'dev/requirements/icon/cases/*.png                                               merge=ours',
241	].join('\n');
242	
243	const attrCtx = (files, gitattributes = GITATTRIBUTES) => ({
244	  files,
245	  allFiles: files,
246	  read: (p) => (p === '.gitattributes' ? gitattributes : null),
247	  exists: () => false,
248	});
249	
250	test("regen-artifacts-merge-ours: fires on a new image kind's snapshots and on an unlisted generated file", () => {
251	  const findings = regenArtifactsMergeOurs.run(
252	    attrCtx([
253	      // a kind added by the self-contained folder drop kinds.js auto-discovers —
254	      // .gitattributes still names only popup/ and icon/
255	      'dev/requirements/badge/cases/badge-states.12.1.png',
256	      'extension/event-extractors/second-list.generated.json',
257	    ]),
258	  );
259	  assert.equal(findings.length, 2);
260	  assert.match(findings[0].what, /dev\/requirements\/badge\/cases\/badge-states\.12\.1\.png/);
261	  // the fix names the DIRECTORY glob for a snapshot, the file itself for a generated one
262	  assert.match(findings[0].fix, /dev\/requirements\/badge\/cases\/\*\.png merge=ours/);
263	  assert.match(findings[1].fix, /extension\/event-extractors\/second-list\.generated\.json merge=ours/);
264	  assert.ok(findings.every((f) => f.severity === 'blocking'));
265	});
266	
267	test('regen-artifacts-merge-ours: quiet on the repo\'s real artifact set', () => {
268	  const findings = regenArtifactsMergeOurs.run(
269	    attrCtx([
270	      'extension/event-extractors/load-order.generated.json',
271	      'dev/requirements/popup/cases/count-label.8.1.png',
272	      'dev/requirements/icon/cases/toolbar-icon.10.1.png',
273	      'extension/events-popup/popup.js', // not an artifact at all
274	      'dev/build/release/store_artifacts/chrome-store-screenshot-1280x800.png', // a PNG outside <kind>/cases/
275	    ]),
276	  );
277	  assert.deepEqual(findings, []);
278	});
279	
280	test('regen-artifacts-merge-ours: leaves the GENERATED-marked files to the canon rule', () => {
281	  // basics/generated-merge-driver owns every name carrying the uppercase marker, so
282	  // this rule must stay silent on one even with no entry in .gitattributes at all.
283	  const findings = regenArtifactsMergeOurs.run(
284	    attrCtx(
285	      ['dev/requirements/extractor/generic-coverage/generic-coverage.GENERATED.md'],
286	      '# nothing on the ours driver here',
287	    ),
288	  );
289	  assert.deepEqual(findings, []);
290	});
291	
292	test('regen-artifacts-merge-ours: honors a basename-only pattern, and a `*` that must not cross a /', () => {
293	  // a pattern with no slash matches by basename at any depth (gitignore semantics)
294	  assert.deepEqual(
295	    regenArtifactsMergeOurs.run(attrCtx(['dev/requirements/popup/cases/count-label.8.1.png'], '*.png merge=ours')),
296	    [],
297	  );
298	  // a single `*` stops at the separator, so a path pattern does not reach a file
299	  // one directory deeper — only `**` does
300	  const deeper = ['extension/event-extractors/load-order.generated.json'];
301	  assert.equal(regenArtifactsMergeOurs.run(attrCtx(deeper, 'extension/*.generated.json merge=ours')).length, 1);
302	  assert.deepEqual(regenArtifactsMergeOurs.run(attrCtx(deeper, 'extension/**/*.generated.json merge=ours')), []);
303	});
304	
305	test('regen-artifacts-merge-ours: quiet when there are no regen artifacts in scope', () => {
306	  assert.deepEqual(regenArtifactsMergeOurs.run(attrCtx(['extension/events-popup/popup.js'])), []);
307	});
